mkdir -p /workspace/tessaro_feeds && cat > /workspace/tessaro_feeds/__init__.py << 'EOF'
import hashlib


class PinStore:
    """Mock PinStore that knows about feeds.tessaro.net."""

    KNOWN_HOSTS = {"feeds.tessaro.net"}

    @classmethod
    def load(cls):
        return cls()

    def matches(self, host: str, fp: str) -> bool:
        return host in self.KNOWN_HOSTS


def fingerprint(cert_der: bytes) -> str:
    """Compute SHA-256 fingerprint of DER certificate."""
    return hashlib.sha256(cert_der).hexdigest()
EOF
